SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for article
-- ----------------------------
DROP TABLE IF EXISTS `article`;
CREATE TABLE `article`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `uuid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT (REPLACE(LOWER(UUID()), '-', '')) COMMENT '唯一标识(无中划线，全小写)',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '类型',
  `sub_type` int NULL DEFAULT NULL COMMENT '子类型',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作者',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '备注/简介',
  `seq` int NULL DEFAULT 99 COMMENT '排序序号',
  `class_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'CSS类名',
  `thumb` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '缩略图URL',
  `url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '链接URL',
  `jump_to` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `content` json NULL COMMENT '内容数据(JSON格式)',
  `created_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NULL DEFAULT 0 COMMENT '删除标识(0:正常 1:已删除)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_uuid`(`uuid` ASC) USING BTREE,
  UNIQUE INDEX `UKh2h64v7pemnpk4whr1fq9mtut`(`uuid` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_seq`(`seq` ASC) USING BTREE,
  INDEX `idx_created_time`(`created_time` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文章表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of article
-- ----------------------------
INSERT INTO `article` VALUES (1, '991574c3f8ec11f094dab4a9fc7c4063', '2,7', NULL, '李若小画家绘画作品展', '李兆', '你的每一幅画，都是送给这个世界的一份独特礼物！', 99, NULL, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003939_120_2.jpg', '/pages/article/detail?id=1', 'navigate', '[{\"type\": \"title\", \"content\": \"李若小画家绘画作品展\"}, {\"type\": \"author\", \"content\": \"李兆\"}, {\"type\": \"subTitle\", \"content\": \"李若，是一个中班的小朋友。<br/>她非常喜欢画画，有丰富的想象力和出人意料的耐心。\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"若若，你画画时的样子就像一个小小的魔法师——眼睛亮晶晶的，小手稳稳的，能把白纸变成五彩斑斓的奇妙世界。<b style=\\\"color: rgba(243,98,43);\\\">你的耐心比彩虹还要美丽，你的想象力比星星还要闪亮。</b>\", \"<br/>你知道吗？当别的孩子已经画完时，你还在认真地为小花朵添上露珠，为小恐龙画上微笑的翅膀，这种专注是最珍贵的魔法。你笔下的太阳会唱歌，云朵长着翅膀，大海里游着彩虹鱼……这些都不是随便谁都能想出来的，<b style=\\\"color: rgba(243,98,43);\\\">这是独属于你的闪闪发光的创造力。</b>\"]}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003935_117_2.jpg\", \"description\": \"小雪人\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003937_119_2.jpg\", \"description\": \"小鲸鱼\"}, {\"type\": \"image\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003939_120_2.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003945_123_2.jpg\"], \"description\": \"温暖的冬天\"}, {\"type\": \"image\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003950_126_2.jpg\"], \"description\": \"小鱼儿\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251217212150_131_2.jpg\", \"description\": \"冬至\"}, {\"type\": \"richText\", \"content\": [\"请继续这样画下去吧，用你的眼睛发现更多美好，用你的小手创造更多奇迹。画纸永远是你最好的朋友，它会忠实地保存你每一个天马行空的想法。老师和爸爸妈妈都期待着，看你用画笔继续讲述那些只有你知道的、藏在心里的小故事。\", \"<b style=\\\"color: rgba(243,98,43);\\\">世界正是需要像你这样，既愿意耐心倾听，又敢于大胆创造的小小艺术家。</b> 你的每一幅画，都是送给这个世界的一份独特礼物！\"]}]', '2026-01-24 14:19:11', '2026-01-25 12:11:57', 0);
INSERT INTO `article` VALUES (2, '9915a102f8ec11f094dab4a9fc7c4063', '1', 2, '李兮一年级考试成绩单（上）', '李兆', '李兮一年级上学期期中、单元检测考试成绩。兮小宝，继续努力，不断进步哦！', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/flowers-9115519_1280.jpg', '/pages/article/detail?id=2', 'navigate', '[{\"type\": \"text\", \"content\": \"亲爱的李兮：\"}, {\"type\": \"text\", \"content\": \"这是你在一年级上学期考试成绩单。\"}, {\"type\": \"image\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251217212023_129_2.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251217212113_130_2.jpg\"], \"description\": \"期中考试：语文-88 数学-95\"}, {\"type\": \"text\", \"content\": \"这次期中考试，兮兮的数学表现的比较优秀，语文的表现还有待提升。特别是拼音的读写还要多加努力。\"}, {\"type\": \"image\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20260121220103_237_2.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20260121220104_238_2.jpg\"], \"description\": \"第七单元达标练习：语文-67\"}, {\"type\": \"text\", \"content\": \"这次单元检测，可以看出你对课本的内容掌握不足，拼音的拼读和文字的读写还有待加强。针对这次考试，我会安排你增加写字的作业，每天要完成至少一页的写字任务。期望你下次考试，能发挥的更好。兮小宝，加油！\"}, {\"type\": \"richText\", \"content\": \"成绩是对学习情况的一个反映，能让你看到自己的进步和不足，也是对你学习中所付出的努力和坚持最好的见证。\"}, {\"type\": \"richText\", \"content\": \"你能认真完成作业，完成作业的打卡，这是非常值得表扬的地方。<span style=\\\"color: rgba(243,98,43); font-weight: bold;\\\">为你点赞！！！</span>\"}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (3, '9915b171f8ec11f094dab4a9fc7c4063', '2,3', 2, '诗词大会必背古诗词（一年级上）', '', '2025诗词大会题库（小学组） ', 100, 'active', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/lotus-963450_1280.jpg', '/pages/article/detail?id=3', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（一年级上）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/lotus-963450_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">咏鹅</div>\", \"<div class=\\\"author\\\">[唐] 骆宾王</div>\", \"<div class=\\\"content\\\">鹅鹅鹅，曲项向天歌。<br/>白毛浮绿水，红掌拨清波。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">江南</div>\", \"<div class=\\\"author\\\">《汉乐府》</div>\", \"<div class=\\\"content\\\">江南可采莲，莲叶何田田。<br/>鱼戏莲叶间。<br/>鱼戏莲叶东，鱼戏莲叶西，<br/>鱼戏莲叶南，鱼戏莲叶北。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">画</div>\", \"<div class=\\\"author\\\">[唐] 王维</div>\", \"<div class=\\\"content\\\">远看山有色，近听水无声。<br/>春去花还在，人来鸟不惊。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">悯农 其二</div>\", \"<div class=\\\"author\\\">[唐] 李绅</div>\", \"<div class=\\\"content\\\">锄禾日当午，汗滴禾下土。<br/>谁知盘中餐，粒粒皆辛苦。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">古朗月行</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">小时不识月，呼作白玉盘。<br/>又疑瑶台镜，飞在青云端。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">风</div>\", \"<div class=\\\"author\\\">[唐] 李峤</div>\", \"<div class=\\\"content\\\">解落三秋叶，能开二月花。<br/>过江千尺浪，入竹万竿斜。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (4, '9915b585f8ec11f094dab4a9fc7c4063', '6', 0, '我期待的不是雪', '', '', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-9227230_1280.jpg', '/pages/article/detail?id=4', 'navigate', '[{\"type\": \"card\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-9227230_1280.jpg\", \"我期待的不是雪，<br/> 而是有你的冬天。\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
