INSERT INTO `article` VALUES (9, '9915d83cf8ec11f094dab4a9fc7c4063', '1', 1, '语文课程39-55页（一年级上）', '李兆', '一年级语文课本教学视频（王老师）', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/一年级上学期语文39页.jpg', '/pages/article/detail?id=9', 'navigate', '[{\"type\": \"title\", \"content\": \"语文课程39-55页（一年级上）\"}, {\"type\": \"subTitle\", \"content\": \"一年级语文课本教学视频（王老师）\"}, {\"type\": \"videoPopup\", \"poster\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/一年级上学期语文39页.jpg\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/video/一年级上学期语文39页.mp4?ratio=1.7778\", \"description\": \"第39页\"}, {\"type\": \"videoPopup\", \"poster\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/一年级上学期语文39页.jpg\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/video/一年级上学期语文39页-2.mp4?ratio=1.7778\", \"description\": \"第39页\"}, {\"type\": \"videoPopup\", \"poster\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/一年级上学期语文52页.jpg\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/video/一年级上学期语文52页.mp4?ratio=1.7778\", \"description\": \"第52页\"}, {\"type\": \"videoPopup\", \"poster\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/一年级上学期语文53页.jpg\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/video/一年级上学期语文53页.mp4?ratio=1.7778\", \"description\": \"第53页\"}, {\"type\": \"videoPopup\", \"poster\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/一年级上学期语文54页.jpg\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/video/一年级上学期语文54页.mp4?ratio=1.7778\", \"description\": \"第54页\"}, {\"type\": \"videoPopup\", \"poster\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/一年级上学期语文54页.jpg\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/video/一年级上学期语文54页-2.mp4?ratio=1.7778\", \"description\": \"第54页\"}, {\"type\": \"videoPopup\", \"poster\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/一年级上学期语文55页.jpg\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/video/一年级上学期语文55页.mp4?ratio=1.7778\", \"description\": \"第55页\"}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (10, '9915dc8af8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（一年级下）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/peach-blossom-5073107_1280.jpg', '/pages/article/detail?id=10', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（一年级下）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/peach-blossom-5073107_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">春晓</div>\", \"<div class=\\\"author\\\">[唐] 孟浩然</div>\", \"<div class=\\\"content\\\">春眠不觉晓，处处闻啼鸟。<br/>夜来风雨声，花落知多少。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">赠汪伦</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">李白乘舟将欲行，忽闻岸上踏歌声。<br/>桃花潭水深千尺，不及汪伦送我情。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">静夜思</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">床前明月光，疑是地上霜。<br/>举头望明月，低头思故乡。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">寻隐者不遇</div>\", \"<div class=\\\"author\\\">[唐] 贾岛</div>\", \"<div class=\\\"content\\\">松下问童子，言师采药去。<br/>只在此山中，云深不知处。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">池上</div>\", \"<div class=\\\"author\\\">[唐] 白居易</div>\", \"<div class=\\\"content\\\">小娃撑小艇，偷采白莲回。<br/>不解藏踪迹，浮萍一道开。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">小池</div>\", \"<div class=\\\"author\\\">[宋] 杨万里</div>\", \"<div class=\\\"content\\\">泉眼无声惜细流，树荫照水爱晴柔。<br/>小荷才露尖尖角，早有蜻蜓立上头。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">画鸡</div>\", \"<div class=\\\"author\\\">[明] 唐寅</div>\", \"<div class=\\\"content\\\">头上红冠不用裁，满身雪白走将来。<br/>平生不敢轻言语，一叫千门万户开。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (11, '9915e8cef8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（二年级上）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/white-plum-blossoms-181159_1280.jpg', '/pages/article/detail?id=11', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（二年级上）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/white-plum-blossoms-181159_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">梅花</div>\", \"<div class=\\\"author\\\">[宋] 王安石</div>\", \"<div class=\\\"content\\\">墙角数枝梅，凌寒独自开。<br/>遥知不是雪，为有暗香来。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">小儿垂钓</div>\", \"<div class=\\\"author\\\">[唐] 胡令能</div>\", \"<div class=\\\"content\\\">蓬头稚子学垂纶，侧坐莓苔草映身。<br/>路人借问遥招手，怕得鱼惊不应人。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">登鹳雀楼</div>\", \"<div class=\\\"author\\\">[唐] 王之涣</div>\", \"<div class=\\\"content\\\">白日依山尽，黄河入海流。<br/>欲穷千里目，更上一层楼。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">望庐山瀑布</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">日照香炉生紫烟，遥看瀑布挂前川。<br/>飞流直下三千尺，疑是银河落九天。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">江雪</div>\", \"<div class=\\\"author\\\">[唐] 柳宗元</div>\", \"<div class=\\\"content\\\">千山鸟飞绝,万径人踪灭。<br/>孤舟蓑笠翁，独钓寒江雪。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">夜宿山寺</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">危楼高百尺，手可摘星辰。<br/>不敢高声语，恐惊天上人。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">敕勒歌</div>\", \"<div class=\\\"author\\\">《北朝民歌》</div>\", \"<div class=\\\"content\\\">敕勒川，阴山下，天似穹庐，笼盖四野。<br/>天苍苍，野茫茫，风吹草低见牛羊。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (12, '9915ebc6f8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（二年级下）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/snow-3904461_1280.jpg', '/pages/article/detail?id=12', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（二年级下）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/snow-3904461_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">村居</div>\", \"<div class=\\\"author\\\">[清] 高鼎</div>\", \"<div class=\\\"content\\\">草长莺飞二月天，拂堤杨柳醉春烟。<br/>儿童散学归来早，忙趁东风放纸鸢。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">咏柳</div>\", \"<div class=\\\"author\\\">[唐] 贺知章</div>\", \"<div class=\\\"content\\\">碧玉妆成一树高，万条垂下绿丝绦。<br/>不知细叶谁裁出，二月春风似剪刀。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">赋得古原草送别</div>\", \"<div class=\\\"author\\\">[唐] 白居易</div>\", \"<div class=\\\"content\\\">离离原上草，一岁一枯荣。<br/>野火烧不尽，春风吹又生。<br/><br/>远芳侵古道，晴翠接荒城。<br/>又送王孙去，萋萋满别情。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">晓出净慈寺送林子方</div>\", \"<div class=\\\"author\\\">[宋] 杨万里</div>\", \"<div class=\\\"content\\\">毕竟西湖六月中，风光不与四时同。<br/>接天莲叶无穷碧，映日荷花别样红。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">绝句</div>\", \"<div class=\\\"author\\\">[唐] 杜甫</div>\", \"<div class=\\\"content\\\">两个黄鹂鸣翠柳，一行白鹭上青天。<br/>窗含西岭千秋雪，门泊东吴万里船。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">悯农</div>\", \"<div class=\\\"author\\\">[唐] 李绅</div>\", \"<div class=\\\"content\\\">春种一粒粟，秋收万颗子。<br/>四海无闲田，农夫犹饿死。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">二十四节气歌</div>\", \"<div class=\\\"author\\\"></div>\", \"<div class=\\\"content\\\">春雨惊春清谷天，夏满芒夏暑相连。<br/>秋处露秋寒霜降，冬雪雪冬小大寒。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">舟夜书所见</div>\", \"<div class=\\\"author\\\">[清] 查慎行</div>\", \"<div class=\\\"content\\\">月黑见渔灯，孤光一点萤。<br/>微微风簇浪，散作满河星。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (13, '99160236f8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（三年级上）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/oranges-5423697_1280.jpg', '/pages/article/detail?id=13', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（三年级上）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/oranges-5423697_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">所见</div>\", \"<div class=\\\"author\\\">[清] 袁枚</div>\", \"<div class=\\\"content\\\">牧童骑黄牛，歌声振林樾。<br/>意欲捕鸣蝉，忽然闭口立。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">山行</div>\", \"<div class=\\\"author\\\">[唐] 杜牧</div>\", \"<div class=\\\"content\\\">远上寒山石径斜，白云生处有人家。<br/>停车坐爱枫林晚，霜叶红于二月花。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">赠刘景文</div>\", \"<div class=\\\"author\\\">[宋] 苏轼</div>\", \"<div class=\\\"content\\\">荷尽已无擎雨盖，菊残犹有傲霜枝。<br/>一年好景君须记，正是橙黄橘绿时。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">夜书所见</div>\", \"<div class=\\\"author\\\">[宋] 叶绍翁</div>\", \"<div class=\\\"content\\\">萧萧梧叶送寒声，江上秋风动客情。<br/>知有儿童挑促织，夜深篱落一灯明。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">望天门山</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">天门中断楚江开，碧水东流至此回。<br/>两岸青山相对出，孤帆一片日边来。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">饮湖上初晴后雨</div>\", \"<div class=\\\"author\\\">[宋] 苏轼</div>\", \"<div class=\\\"content\\\">水光潋滟晴方好，山色空蒙雨亦奇。<br/>欲把西湖比西子，淡妆浓抹总相宜。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">望洞庭</div>\", \"<div class=\\\"author\\\">[唐] 刘禹锡</div>\", \"<div class=\\\"content\\\">湖光秋月两相和，潭面无风镜未磨。<br/>遥望洞庭山水翠，白银盘里一青螺。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">早发白帝城</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">朝辞白帝彩云间，千里江陵一日还。<br/>两岸猿声啼不住，轻舟已过万重山。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">采莲曲</div>\", \"<div class=\\\"author\\\">[唐] 王昌龄</div>\", \"<div class=\\\"content\\\">荷叶罗裙一色裁，芙蓉向脸两边开。<br/>乱入池中看不见，闻歌始觉有人来。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (14, '99160b2bf8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（三年级下）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/barn-swallow-10043616_1280.webp', '/pages/article/detail?id=14', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（三年级下）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/barn-swallow-10043616_1280.webp\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">绝句</div>\", \"<div class=\\\"author\\\">[唐] 杜甫</div>\", \"<div class=\\\"content\\\">迟日江山丽，春风花草香。<br/>泥融飞燕子，沙暖睡鸳鸯。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">惠崇春江晚景</div>\", \"<div class=\\\"author\\\">[宋] 苏轼</div>\", \"<div class=\\\"content\\\">竹外桃花三两枝，春江水暖鸭先知。<br/>蒌蒿满地芦芽短，正是河豚欲上时。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">三衢道中</div>\", \"<div class=\\\"author\\\">[宋] 曾几</div>\", \"<div class=\\\"content\\\">梅子黄时日日晴，小溪泛尽却山行。<br/>绿阴不减来时路，添得黄鹂四五声。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">忆江南</div>\", \"<div class=\\\"author\\\">[唐] 白居易</div>\", \"<div class=\\\"content\\\">江南好，风景旧曾谙。<br/>日出江花红胜火，春来江水绿如蓝。<br/>能不忆江南？</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">元日</div>\", \"<div class=\\\"author\\\">[宋] 王安石</div>\", \"<div class=\\\"content\\\">爆竹声中一岁除，春风送暖入屠苏。<br/>千门万户曈曈日，总把新桃换旧符。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">清明</div>\", \"<div class=\\\"author\\\">[唐] 杜牧</div>\", \"<div class=\\\"content\\\">清明时节雨纷纷，路上行人欲断魂。<br/>借问酒家何处有？牧童遥指杏花村。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">九月九日忆山东兄弟</div>\", \"<div class=\\\"author\\\">[唐] 王维</div>\", \"<div class=\\\"content\\\">独在异乡为异客，每逢佳节倍思亲。<br/>遥知兄弟登高处，遍插茱萸少一人。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">滁州西涧</div>\", \"<div class=\\\"author\\\">[唐] 韦应物</div>\", \"<div class=\\\"content\\\">独怜幽草涧边生，上有黄鹂深树鸣。<br/>春潮带雨晚来急，野渡无人舟自横。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">大林寺桃花</div>\", \"<div class=\\\"author\\\">[唐] 白居易</div>\", \"<div class=\\\"content\\\">人间四月芳菲尽，山寺桃花始盛开。<br/>长恨春归无觅处，不知转入此中来。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (15, '99160ebaf8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（四年级上）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/roe-deer-5502246_1280.jpg', '/pages/article/detail?id=15', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（四年级上）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/roe-deer-5502246_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">浪淘沙</div>\", \"<div class=\\\"author\\\">[唐] 刘禹锡</div>\", \"<div class=\\\"content\\\">八月涛声吼地来，头高数丈触山回。<br/>须臾却入海门去，卷起沙堆似雪堆。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">鹿柴</div>\", \"<div class=\\\"author\\\">[唐] 王维</div>\", \"<div class=\\\"content\\\">空山不见人，但闻人语响。<br/>返景入深林，复照青苔上。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">暮江吟</div>\", \"<div class=\\\"author\\\">[唐] 白居易</div>\", \"<div class=\\\"content\\\">一道残阳铺水中，半江瑟瑟半江红。<br/>可怜九月初三夜，露似真珠月似弓。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">题西林壁</div>\", \"<div class=\\\"author\\\">[宋] 苏轼</div>\", \"<div class=\\\"content\\\">横看成岭侧成峰，远近高低各不同。<br/>不识庐山真面目，只缘身在此山中。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">雪梅</div>\", \"<div class=\\\"author\\\">[宋] 卢钺</div>\", \"<div class=\\\"content\\\">梅雪争春未肯降，骚人阁笔费评章。<br/>梅须逊雪三分白，雪却输梅一段香。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">嫦娥</div>\", \"<div class=\\\"author\\\">[唐] 李商隐</div>\", \"<div class=\\\"content\\\">云母屏风烛影深，长河渐落晓星沉。<br/>嫦娥应悔偷灵药，碧海青天夜夜心。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">出塞</div>\", \"<div class=\\\"author\\\">[唐] 王昌龄</div>\", \"<div class=\\\"content\\\">秦时明月汉时关，万里长征人未还。<br/>但使龙城飞将在，不教胡马度阴山。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">凉州词</div>\", \"<div class=\\\"author\\\">[唐] 王翰</div>\", \"<div class=\\\"content\\\">葡萄美酒夜光杯，欲饮琵琶马上催。<br/>醉卧沙场君莫笑，古来征战几人回。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">夏日绝句</div>\", \"<div class=\\\"author\\\">[宋] 李清照</div>\", \"<div class=\\\"content\\\">生当作人杰，死亦为鬼雄。<br/>至今思项羽，不肯过江东。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">别董大</div>\", \"<div class=\\\"author\\\">[唐] 高适</div>\", \"<div class=\\\"content\\\">千里黄云白日曛，北风吹雁雪纷纷。<br/>莫愁前路无知己，天下谁人不识君。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (16, '991611aff8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（四年级下）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/bee-6127510_1280.jpg', '/pages/article/detail?id=16', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（四年级下）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/bee-6127510_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">宿新市徐公店</div>\", \"<div class=\\\"author\\\">[宋] 杨万里</div>\", \"<div class=\\\"content\\\">篱落疏疏一径深，树头新绿未成阴。<br/>儿童急走追黄蝶，飞入菜花无处寻。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">四时田园杂兴</div>\", \"<div class=\\\"author\\\">[宋] 范成大</div>\", \"<div class=\\\"content\\\">梅子金黄杏子肥，麦花雪白菜花稀。<br/>日长篱落无人过，惟有蜻蜓蛱蝶飞。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">清平乐·村居</div>\", \"<div class=\\\"author\\\">[宋] 辛弃疾</div>\", \"<div class=\\\"content\\\">茅檐低小，溪上青青草。<br/>醉里吴音相媚好，白发谁家翁媪？<br/><br/>大儿锄豆溪东，中儿正织鸡笼。<br/>最喜小儿亡赖，溪头卧剥莲蓬。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">卜算子·咏梅</div>\", \"<div class=\\\"author\\\">毛泽东</div>\", \"<div class=\\\"content\\\">风雨送春归，飞雪迎春到。<br/>已是悬崖百丈冰，犹有花枝俏。<br/>俏也不争春，只把春来报。<br/>待到山花烂漫时，她在丛中笑。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">江畔独步寻花</div>\", \"<div class=\\\"author\\\">[唐] 杜甫\\t</div>\", \"<div class=\\\"content\\\">黄师塔前江水东，春光懒困倚微风。<br/>桃花一簇开无主，可爱深红爱浅红？</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">蜂</div>\", \"<div class=\\\"author\\\">[唐] 罗隐</div>\", \"<div class=\\\"content\\\">不论平地与山尖，无限风光尽被占。<br/>采得百花成蜜后，为谁辛苦为谁甜。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">独坐敬亭山</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">众鸟高飞尽，孤云独去闲。<br/>相看两不厌，只有敬亭山。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">芙蓉楼送辛渐</div>\", \"<div class=\\\"author\\\">[唐] 王昌龄</div>\", \"<div class=\\\"content\\\">寒雨连江夜入吴，平明送客楚山孤。<br/>洛阳亲友如相问，一片冰心在玉壶。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">塞下曲</div>\", \"<div class=\\\"author\\\">[唐] 卢纶</div>\", \"<div class=\\\"content\\\">月黑雁飞高，单于夜遁逃。<br/>欲将轻骑逐，大雪满弓刀。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">墨梅</div>\", \"<div class=\\\"author\\\">[元] 王冕</div>\", \"<div class=\\\"content\\\">我家洗砚池边树，朵朵花开淡墨痕。<br/>不要人夸颜色好，只留清气满乾坤。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (17, '991615a6f8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（五年级上）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/cicada-115913_1280.jpg', '/pages/article/detail?id=17', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（五年级上）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/cicada-115913_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">蝉</div>\", \"<div class=\\\"author\\\">[唐] 虞世南\\t</div>\", \"<div class=\\\"content\\\">垂緌饮清露，流响出疏桐。<br/>居高声自远，非是藉秋风。 </div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">乞巧</div>\", \"<div class=\\\"author\\\">[唐] 林杰</div>\", \"<div class=\\\"content\\\">七夕今宵看碧霄，牵牛织女渡河桥。<br/>家家乞巧望秋月，穿尽红丝几万条。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">示儿</div>\", \"<div class=\\\"author\\\">[宋] 陆游</div>\", \"<div class=\\\"content\\\">死去元知万事空，但悲不见九州同。<br/>王师北定中原日，家祭无忘告乃翁。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">题临安邸</div>\", \"<div class=\\\"author\\\">[宋] 林升</div>\", \"<div class=\\\"content\\\">山外青山楼外楼，西湖歌舞几时休？<br/>暖风熏得游人醉，直把杭州作汴州。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">己亥杂诗</div>\", \"<div class=\\\"author\\\">[清] 龚自珍</div>\", \"<div class=\\\"content\\\">九州生气恃风雷，万马齐喑究可哀。<br/>我劝天公重抖擞，不拘一格降人才。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">山居秋暝</div>\", \"<div class=\\\"author\\\">[唐] 王维</div>\", \"<div class=\\\"content\\\">空山新雨后，天气晚来秋。<br/>明月松间照，清泉石上流。<br/><br/>竹喧归浣女，莲动下渔舟。<br/>随意春芳歇，王孙自可留。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">枫桥夜泊</div>\", \"<div class=\\\"author\\\">[唐] 张继</div>\", \"<div class=\\\"content\\\">月落乌啼霜满天，江枫渔火对愁眠。<br/>姑苏城外寒山寺，夜半钟声到客船。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">长相思</div>\", \"<div class=\\\"author\\\">[清] 纳兰性德</div>\", \"<div class=\\\"content\\\">山一程，水一程，<br/>身向榆关那畔行，夜深千帐灯。<br/><br/>风一更，雪一更，<br/>聒碎乡心梦不成，故园无此声。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">渔歌子</div>\", \"<div class=\\\"author\\\">[唐] 张志和</div>\", \"<div class=\\\"content\\\">西塞山前白鹭飞，桃花流水鳜鱼肥。<br/>青箬笠，绿蓑衣，斜风细雨不须归。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">观书有感 其一</div>\", \"<div class=\\\"author\\\">[宋] 朱熹</div>\", \"<div class=\\\"content\\\">半亩方塘一鉴开，天光云影共徘徊。<br/>问渠那得清如许？为有源头活水来。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">观书有感 其二</div>\", \"<div class=\\\"author\\\">[宋] 朱熹</div>\", \"<div class=\\\"content\\\">昨夜江边春水生，艨艟巨舰一毛轻。<br/>向来枉费推移力，此日中流自在行。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (18, '99161a47f8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（五年级下）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/horse-9815867_1280.webp', '/pages/article/detail?id=18', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（五年级下）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/horse-9815867_1280.webp\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">四时田园杂兴</div>\", \"<div class=\\\"author\\\">[宋] 范成大</div>\", \"<div class=\\\"content\\\">昼出耘田夜绩麻，村庄儿女各当家。<br/>童孙未解供耕织，也傍桑阴学种瓜。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">稚子弄冰</div>\", \"<div class=\\\"author\\\">[宋] 杨万里</div>\", \"<div class=\\\"content\\\">稚子金盆脱晓冰，彩丝穿取当银铮。<br/>敲成玉磬穿林响，忽作玻璃碎地声。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">村晚</div>\", \"<div class=\\\"author\\\">[宋] 雷震</div>\", \"<div class=\\\"content\\\">草满池塘水满陂，山衔落日浸寒漪。<br/>牧童归去横牛背，短笛无腔信口吹。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">游子吟</div>\", \"<div class=\\\"author\\\">[唐] 孟郊\\t</div>\", \"<div class=\\\"content\\\">慈母手中线，游子身上衣。<br/>临行密密缝，意恐迟迟归。<br/>谁言寸草心，报得三春晖。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">鸟鸣涧</div>\", \"<div class=\\\"author\\\">[唐] 王维</div>\", \"<div class=\\\"content\\\">人闲桂花落，夜静春山空。<br/>月出惊山鸟，时鸣春涧中。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">从军行</div>\", \"<div class=\\\"author\\\">[唐] 王昌龄\\t</div>\", \"<div class=\\\"content\\\">青海长云暗雪山，孤城遥望玉门关。<br/>黄沙百战穿金甲，不破楼兰终不还。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">秋夜将晓出篱门迎凉有感</div>\", \"<div class=\\\"author\\\">[宋] 陆游</div>\", \"<div class=\\\"content\\\">三万里河东入海，五千仞岳上摩天。<br/>遗民泪尽胡尘里，南望王师又一年。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">闻官军收河南河北</div>\", \"<div class=\\\"author\\\">[唐] 杜甫</div>\", \"<div class=\\\"content\\\">剑外忽传收蓟北，初闻涕泪满衣裳。<br/>却看妻子愁何在，漫卷诗书喜欲狂。<br/><br/>白日放歌须纵酒，青春作伴好还乡。<br/>即从巴峡穿巫峡，便下襄阳向洛阳。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">凉州词</div>\", \"<div class=\\\"author\\\">[唐] 王之涣</div>\", \"<div class=\\\"content\\\">黄河远上白云间，一片孤城万仞山。<br/>羌笛何须怨杨柳，春风不度玉门关。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">黄鹤楼送孟浩然之广陵</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">故人西辞黄鹤楼，烟花三月下扬州。<br/>孤帆远影碧空尽，唯见长江天际流。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">乡村四月</div>\", \"<div class=\\\"author\\\">[宋] 翁卷</div>\", \"<div class=\\\"content\\\">绿遍山原白满川，子规声里雨如烟。<br/>乡村四月闲人少，才了蚕桑又插田。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (19, '9916231bf8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（六年级上）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-9023056_1280.png', '/pages/article/detail?id=19', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（六年级上）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-9023056_1280.png\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">宿建德江</div>\", \"<div class=\\\"author\\\">[唐] 孟浩然</div>\", \"<div class=\\\"content\\\">移舟泊烟渚，日暮客愁新。<br/>野旷天低树，江清月近人。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">六月二十七日望湖楼醉书</div>\", \"<div class=\\\"author\\\">[宋] 苏轼</div>\", \"<div class=\\\"content\\\">黑云翻墨未遮山，白雨跳珠乱入船。<br/>卷地风来忽吹散，望湖楼下水如天。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">西江月·夜行黄沙道中</div>\", \"<div class=\\\"author\\\">[宋] 辛弃疾</div>\", \"<div class=\\\"content\\\">明月别枝惊鹊，清风半夜鸣蝉。<br/>稻花香里说丰年，听取蛙声一片。<br/><br/>七八个星天外，两三点雨山前。<br/>旧时茅店社林边，路转溪桥忽见。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">过故人庄</div>\", \"<div class=\\\"author\\\">[唐] 孟浩然</div>\", \"<div class=\\\"content\\\">故人具鸡黍，邀我至田家。<br/>绿树村边合，青山郭外斜。<br/><br/>开轩面场圃，把酒话桑麻。<br/>待到重阳日，还来就菊花。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">七律·长征</div>\", \"<div class=\\\"author\\\">毛泽东</div>\", \"<div class=\\\"content\\\">红军不怕远征难，万水千山只等闲。<br/>五岭逶迤腾细浪，乌蒙磅礴走泥丸。<br/>金沙水拍云崖暖，大渡桥横铁索寒。<br/>更喜岷山千里雪，三军过后尽开颜。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">菩萨蛮·大柏地</div>\", \"<div class=\\\"author\\\">毛泽东</div>\", \"<div class=\\\"content\\\">赤橙黄绿青蓝紫，谁持彩练当空舞？<br/>雨后复斜阳，关山阵阵苍。<br/>当年鏖战急，弹洞前村壁。<br/>装点此关山，今朝更好看。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">春日</div>\", \"<div class=\\\"author\\\">[宋] 朱熹</div>\", \"<div class=\\\"content\\\">胜日寻芳泗水滨，无边光景一时新。<br/>等闲识得东风面，万紫千红总是春。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">回乡偶书</div>\", \"<div class=\\\"author\\\">[唐] 贺知章</div>\", \"<div class=\\\"content\\\">少小离家老大回，乡音无改鬓毛衰。<br/>儿童相见不相识，笑问客从何处来。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">浪淘沙</div>\", \"<div class=\\\"author\\\">[唐] 刘禹锡</div>\", \"<div class=\\\"content\\\">九曲黄河万里沙，浪淘风簸自天涯。<br/>如今直上银河去，同到牵牛织女家。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">江南春</div>\", \"<div class=\\\"author\\\">[唐] 杜牧</div>\", \"<div class=\\\"content\\\">千里莺啼绿映红，水村山郭酒旗风。<br/>南朝四百八十寺，多少楼台烟雨中。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">书湖阴先生壁</div>\", \"<div class=\\\"author\\\">[宋] 王安石</div>\", \"<div class=\\\"content\\\">茅檐长扫净无苔，花木成畦手自栽。<br/>一水护田将绿绕，两山排闼送青来。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (20, '99162812f8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（六年级下）', '', '2025诗词大会题库（小学组） ', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/white-horse-3010129_1280.jpg', '/pages/article/detail?id=20', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（六年级下）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/white-horse-3010129_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">寒食</div>\", \"<div class=\\\"author\\\">[唐] 韩翃</div>\", \"<div class=\\\"content\\\">春城无处不飞花，寒食东风御柳斜。<br/>日暮汉宫传蜡烛，轻烟散入五侯家。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">迢迢牵牛星</div>\", \"<div class=\\\"author\\\">《古诗十九首》</div>\", \"<div class=\\\"content\\\">迢迢牵牛星，皎皎河汉女。<br/>纤纤擢素手，札札弄机杼。<br/>终日不成章，泣涕零如雨；<br/>河汉清且浅，相去复几许！<br/>盈盈一水间，脉脉不得语。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">十五夜望月</div>\", \"<div class=\\\"author\\\">[唐] 王建</div>\", \"<div class=\\\"content\\\">中庭地白树栖鸦，冷露无声湿桂花。<br/>今夜月明人尽望，不知秋思落谁家。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">长歌行</div>\", \"<div class=\\\"author\\\">汉乐府</div>\", \"<div class=\\\"content\\\">青青园中葵，朝露待日晞。<br/>阳春布德泽，万物生光辉。<br/>常恐秋节至，焜黄华叶衰。<br/>百川东到海，何时复西归。<br/>少壮不努力，老大徒伤悲！</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">马诗</div>\", \"<div class=\\\"author\\\">[唐] 李贺</div>\", \"<div class=\\\"content\\\">大漠沙如雪，燕山月似钩。<br/>何当金络脑，快走踏清秋。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">石灰吟</div>\", \"<div class=\\\"author\\\">[明] 于谦</div>\", \"<div class=\\\"content\\\">千锤万凿出深山，烈火焚烧若等闲。<br/>粉骨碎身浑不怕，要留清白在人间。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">竹石</div>\", \"<div class=\\\"author\\\">[清] 郑燮</div>\", \"<div class=\\\"content\\\">咬定青山不放松，立根原在破岩中。<br/>千磨万击还坚劲，任尔东西南北风。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">采薇 节选</div>\", \"<div class=\\\"author\\\">《诗经·小雅》</div>\", \"<div class=\\\"content\\\">昔我往矣，杨柳依依。<br/>今我来思，雨雪霏霏。<br/>行道迟迟，载渴载饥。<br/>我心伤悲，莫知我哀！</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">送元二使安西</div>\", \"<div class=\\\"author\\\">[唐] 王维</div>\", \"<div class=\\\"content\\\">渭城朝雨浥轻尘，客舍青青柳色新。<br/>劝君更尽一杯酒，西出阳关无故人。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">春夜喜雨</div>\", \"<div class=\\\"author\\\">[唐] 杜甫</div>\", \"<div class=\\\"content\\\">好雨知时节，当春乃发生。<br/>随风潜入夜，润物细无声。<br/>野径云俱黑，江船火独明。<br/>晓看红湿处，花重锦官城。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">早春呈水部张十八员外</div>\", \"<div class=\\\"author\\\">[唐] 韩愈</div>\", \"<div class=\\\"content\\\">天街小雨润如酥，草色遥看近却无。<br/>最是一年春好处，绝胜烟柳满皇都。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">江上渔者</div>\", \"<div class=\\\"author\\\">[宋] 范仲淹</div>\", \"<div class=\\\"content\\\">江上往来人，但爱鲈鱼美。<br/>君看一叶舟，出没风波里。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">泊船瓜洲</div>\", \"<div class=\\\"author\\\">[宋] 王安石</div>\", \"<div class=\\\"content\\\">京口瓜洲一水间，钟山只隔数重山。<br/>春风又绿江南岸，明月何时照我还？</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">游园不值</div>\", \"<div class=\\\"author\\\">[宋] 叶绍翁</div>\", \"<div class=\\\"content\\\">应怜屐齿印苍苔，小扣柴扉久不开。<br/>春色满园关不住，一枝红杏出墙来。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">卜算子·送鲍浩然之浙东</div>\", \"<div class=\\\"author\\\">[宋] 王观</div>\", \"<div class=\\\"content\\\">水是眼波横，山是眉峰聚。<br/>欲问行人去那边？眉眼盈盈处。<br/><br/>才始送春归，又送君归去。<br/>若到江南赶上春，千万和春住。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">浣溪沙·游蕲水清泉寺</div>\", \"<div class=\\\"author\\\">[宋] 苏轼</div>\", \"<div class=\\\"content\\\">山下兰芽短浸溪，松间沙路净无泥，<br/>潇潇暮雨子规啼。谁道人生无再少？<br/>门前流水尚能西！休将白发唱黄鸡。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">清平乐·春归何处</div>\", \"<div class=\\\"author\\\">[宋] 黄庭坚</div>\", \"<div class=\\\"content\\\">春归何处。寂寞无行路。<br/>若有人知春去处。唤取归来同住。<br/>春无踪迹谁知。除非问取黄鹂。<br/>百啭无人能解，因风飞过蔷薇。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (21, '99165020f8ec11f094dab4a9fc7c4063', '3', 2, '诗词大会必背古诗词（初中）', '', '2025诗词大会题库（7-9年级）', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/sunset-4241457_1280.jpg', '/pages/article/detail?id=21', 'navigate', '[{\"type\": \"title\", \"content\": \"诗词大会必背古诗词（初中）\"}, {\"type\": \"subTitle\", \"content\": \"本诗词库共选取了210首诗词。其中，选自统编版小学语文教科书古诗词116首，统编教材七至九年级教科书古诗词30首，红色诗词24首，美丽江西7首，赣南诗词10首，课外诗词23首。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/sunset-4241457_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">闻王昌龄左迁龙标遥有此寄</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">杨花落尽子规啼，闻道龙标过五溪。\\n我寄愁心与明月，随君直到夜郎西。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">天净沙·秋思</div>\", \"<div class=\\\"author\\\">[元] 马致远</div>\", \"<div class=\\\"content\\\">枯藤老树昏鸦，\\n小桥流水人家，\\n古道西风瘦马。\\n夕阳西下，\\n断肠人在天涯。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">次北固山下 </div>\", \"<div class=\\\"author\\\">[唐] 王湾</div>\", \"<div class=\\\"content\\\">客路青山外，行舟绿水前。\\n潮平两岸阔，风正一帆悬。\\n海日生残夜，江春入旧年。\\n乡书何处达，归雁洛阳边。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">峨眉山月歌</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">峨眉山月半轮秋，影入平羌江水流。\\n夜发清溪向三峡，思君不见下渝州。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">江南逢李龟年 </div>\", \"<div class=\\\"author\\\">[唐] 杜甫</div>\", \"<div class=\\\"content\\\">岐王宅里寻常见，崔九堂前几度闻。\\n正是江南好风景，落花时节又逢君。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">夜上受降城闻笛 </div>\", \"<div class=\\\"author\\\">[唐] 李益</div>\", \"<div class=\\\"content\\\">回乐烽前沙似雪，受降城外月如霜。\\n不知何处吹芦管，一夜征人尽望乡。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">秋词（其一）</div>\", \"<div class=\\\"author\\\">[唐] 刘禹锡</div>\", \"<div class=\\\"content\\\">自古逢秋悲寂寥，我言秋日胜春朝。\\n晴空一鹤排云上，便引诗情到碧霄。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">夜雨寄北 </div>\", \"<div class=\\\"author\\\">[唐] 李商隐</div>\", \"<div class=\\\"content\\\">君问归期未有期，巴山夜雨涨秋池。\\n何当共剪西窗烛，却话巴山夜雨时。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">十一月四日风雨大作</div>\", \"<div class=\\\"author\\\">[宋] 陆游</div>\", \"<div class=\\\"content\\\">僵卧孤村不自哀，尚思为国戍轮台。\\n夜阑卧听风吹雨，铁马冰河入梦来。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">竹里馆 </div>\", \"<div class=\\\"author\\\">[唐] 王维</div>\", \"<div class=\\\"content\\\">独坐幽篁里，弹琴复长啸。\\n深林人不知，明月来相照。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">春夜洛城闻笛 </div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">谁家玉笛暗飞声，散入春风满洛城。\\n此夜曲中闻折柳，何人不起故园情。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">晚春 </div>\", \"<div class=\\\"author\\\">[唐] 韩愈</div>\", \"<div class=\\\"content\\\">草树知春不久归，百般红紫斗芳菲。\\n杨花榆荚无才思，惟解漫天作雪飞。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">登幽州台歌</div>\", \"<div class=\\\"author\\\">[唐] 陈子昂</div>\", \"<div class=\\\"content\\\">前不见古人，后不见来者。\\n念天地之悠悠，独怆然而涕下！</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">望岳 </div>\", \"<div class=\\\"author\\\">[唐] 杜甫</div>\", \"<div class=\\\"content\\\">岱宗夫如何，齐鲁青未了。\\n造化钟神秀，阴阳割昏晓。\\n荡胸生曾云，决眦入归鸟。\\n会当凌绝顶，一览众山小。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">登飞来峰</div>\", \"<div class=\\\"author\\\">[宋] 王安石</div>\", \"<div class=\\\"content\\\">飞来山上千寻塔，闻说鸡鸣见日升。\\n不畏浮云遮望眼，自缘身在最高层。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">泊秦淮 </div>\", \"<div class=\\\"author\\\">[唐] 杜牧</div>\", \"<div class=\\\"content\\\">烟笼寒水月笼沙，夜泊秦淮近酒家。\\n商女不知亡国恨，隔江犹唱后庭花。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">约客 </div>\", \"<div class=\\\"author\\\">[宋] 赵师秀</div>\", \"<div class=\\\"content\\\">黄梅时节家家雨，青草池塘处处蛙。\\n有约不来过夜半，闲敲棋子落灯花。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">黄鹤楼 </div>\", \"<div class=\\\"author\\\">[唐] 崔颢</div>\", \"<div class=\\\"content\\\">昔人已乘黄鹤去，此地空余黄鹤楼。\\n黄鹤一去不复返，白云千载空悠悠。\\n晴川历历汉阳树，芳草萋萋鹦鹉洲。\\n日暮乡关何处是？烟波江上使人愁。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">钱塘湖春行 </div>\", \"<div class=\\\"author\\\">[唐] 白居易</div>\", \"<div class=\\\"content\\\">孤山寺北贾亭西，水面初平云脚低。\\n几处早莺争暖树，谁家新燕啄春泥。\\n乱花渐欲迷人眼，浅草才能没马蹄。\\n最爱湖东行不足，绿杨阴里白沙堤。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">春望 </div>\", \"<div class=\\\"author\\\">[唐] 杜甫</div>\", \"<div class=\\\"content\\\">国破山河在，城春草木深。\\n感时花溅泪，恨别鸟惊心。\\n烽火连三月，家书抵万金。\\n白头搔更短，浑欲不胜簪。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">赤壁</div>\", \"<div class=\\\"author\\\">[唐] 杜牧</div>\", \"<div class=\\\"content\\\">折戟沉沙铁未销，自将磨洗认前朝。\\n东风不与周郎便，铜雀春深锁二乔。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">浣溪沙</div>\", \"<div class=\\\"author\\\">[宋] 晏殊</div>\", \"<div class=\\\"content\\\">一曲新词酒一杯，\\n去年天气旧亭台。\\n夕阳西下几时回？\\n\\n无可奈何花落去，\\n似曾相识燕归来。\\n小园香径独徘徊。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">如梦令</div>\", \"<div class=\\\"author\\\">[宋] 李清照</div>\", \"<div class=\\\"content\\\">常记溪亭日暮，沉醉不知归路。\\n兴尽晚回舟，误入藕花深处。\\n争渡，争渡，惊起一滩鸥鹭。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">送杜少府之任蜀州</div>\", \"<div class=\\\"author\\\">[唐] 王勃</div>\", \"<div class=\\\"content\\\">城阙辅三秦，风烟望五津。\\n与君离别意，同是宦游人。\\n海内存知己，天涯若比邻。\\n无为在歧路，儿女共沾巾。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">送友人</div>\", \"<div class=\\\"author\\\">[唐] 李白</div>\", \"<div class=\\\"content\\\">青山横北郭，白水绕东城。\\n此地一为别，孤蓬万里征。\\n浮云游子意，落日故人情。\\n挥手自兹去，萧萧班马鸣。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">无题</div>\", \"<div class=\\\"author\\\">[唐] 李商隐</div>\", \"<div class=\\\"content\\\">相见时难别亦难，东风无力百花残。\\n春蚕到死丝方尽，蜡炬成灰泪始干。\\n晓镜但愁云鬓改，夜吟应觉月光寒。\\n蓬山此去无多路，青鸟殷勤为探看。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">过零丁洋 </div>\", \"<div class=\\\"author\\\">[宋] 文天祥</div>\", \"<div class=\\\"content\\\">辛苦遭逢起一经，干戈寥落四周星。\\n山河破碎风飘絮，身世浮沉雨打萍。\\n惶恐滩头说惶恐，零丁洋里叹零丁。\\n人生自古谁无死，留取丹心照汗青。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">水调歌头</div>\", \"<div class=\\\"author\\\">[宋] 苏轼</div>\", \"<div class=\\\"content\\\">明月几时有？把酒问青天。\\n不知天上宫阙，今夕是何年？\\n我欲乘风归去，又恐琼楼玉宇，\\n高处不胜寒。\\n起舞弄清影，何似在人间？\\n\\n转朱阁，低绮户，照无眠。\\n不应有恨，何事长向别时圆？\\n人有悲欢离合，月有阴晴圆缺，\\n此事古难全。但愿人长久，\\n千里共婵娟。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">卜算子·咏梅 </div>\", \"<div class=\\\"author\\\">[宋] 陆游</div>\", \"<div class=\\\"content\\\">驿外断桥边，寂寞开无主。\\n已是黄昏独自愁，更着风和雨。\\n无意苦争春，一任群芳妒。\\n零落成泥碾作尘，只有香如故。</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">饮酒（其五）</div>\", \"<div class=\\\"author\\\">[晋] 陶渊明</div>\", \"<div class=\\\"content\\\">结庐在人境，而无车马喧。\\n问君何能尔？心远地自偏。\\n采菊东篱下，悠然见南山。\\n山气日夕佳，飞鸟相与还。\\n此中有真意，欲辨已忘言。</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (22, '99167315f8ec11f094dab4a9fc7c4063', '3', 3, '大班口才训练（1-7篇）', '', '幼儿园大班2025春口才训练，总15篇', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/rabbit-9926492_1280.webp', '/pages/article/detail?id=22', 'navigate', '[{\"type\": \"title\", \"content\": \"大班口才训练（1-7篇）\"}, {\"type\": \"subTitle\", \"content\": \"幼儿园大班2025春口才训练，总15篇。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/rabbit-9926492_1280.webp\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《糊涂小猪》</div>\", \"\", \"<div class=\\\"content\\\">胖小猪，圆圆肚，\\n圆圆脑瓜好糊涂。\\n出大门，撞了树;\\n上学校，忘了书;\\n转回家，迷了路。\\n呜呜呜，只会哭:\\n奶奶快来抱抱我，\\n忘了家在哪儿住!</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《猜猜我有多爱你》\", \"\", \"<div class=\\\"content\\\">妈妈，猜猜我有多爱你。\\n我爱你像围巾那么暖，\\n我爱你像大树那么高；\\n我爱你像大海那么深，\\n我爱你像糖果那么甜。\\n我爱你很多很多！\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《哈哈镜》\", \"\", \"<div class=\\\"content\\\">快来照，快来照，\\n一照你就哈哈笑！\\n这么胖，这么瘦，\\n这么矮，这么高。\\n镜里有个滑稽人，\\n和我一起蹦蹦跳。\\n哈哈哈，哈哈哈。\\n怎么我笑他也笑？</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《爱祖国》\", \"\", \"<div class=\\\"content\\\">国旗国旗红又红，\\n国旗上面五颗星。\\n一颗大，四颗小，\\n闪闪发光亮晶晶。\\n国旗国旗我爱你，\\n我们向你敬个礼。\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《乌龟找朋友》\", \"\", \"<div class=\\\"content\\\">小乌龟，找朋友，\\n慢慢悠悠河边走。\\n它嫌小猴太调皮，\\n又嫌河马样子丑。\\n它嫌青蛙呱呱叫，\\n又嫌螃蟹横着走。\\n挑来挑去没朋友，\\n自己缩回壳里头。\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《清明谣》\", \"\", \"<div class=\\\"content\\\">清明节，雨飘飘，\\n大地穿上绿旗袍。\\n采艾叶，做青团，\\n香香甜甜味道好。\\n放风筝，荡秋千，\\n和和美美真热闹。\\n祭祖先，要敬孝，\\n家风传承很重要。\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《不不兔》\", \"\", \"<div class=\\\"content\\\">有只小兔爱说“不”，\\n人们叫它“不不兔”。\\n妈妈叫它扫扫地，\\n小兔连说“不不不”。\\n爸爸催它做算术，\\n小兔又说“不不不”。\\n爷爷让它浇浇花，\\n它脑袋摇成拨浪鼓。\\n小朋友约它去种树，\\n“不”字好像糖葫芦。\\n不不兔，真糊涂，\\n“不”字说多了，\\n嘴唇再也合不住⋯⋯</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (23, '9916778ef8ec11f094dab4a9fc7c4063', '3', 3, '大班口才训练（8-15篇）', '', '幼儿园大班2025春口才训练，总15篇', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/water-3093587_1280.jpg', '/pages/article/detail?id=23', 'navigate', '[{\"type\": \"title\", \"content\": \"大班口才训练（8-15篇）\"}, {\"type\": \"subTitle\", \"content\": \"幼儿园大班2025春口才训练，总15篇。\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/water-3093587_1280.jpg\", \"className\": \"full_width\"}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《大海睡了》\", \"\", \"<div class=\\\"content\\\">风儿不闹了，\\n浪儿不笑了。\\n深夜里，\\n大海睡觉了。\\n她抱着明月，\\n她背着星星。\\n那轻轻的潮声啊，\\n是她睡熟的鼾声。\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《中国茶》\", \"\", \"<div class=\\\"content\\\">中国茶叶千万多，\\n我给大家说几个：绿茶、红茶、乌龙茶；\\n白茶、花茶、紧压茶；\\n青茶、黑茶、速溶茶；\\n平地、高山、丘陵茶；\\n这些个茶，那些个茶，\\n多喝身体顶呱呱！顶呱呱！\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《劳动赞歌》\", \"\", \"<div class=\\\"content\\\">五一五一劳动节，\\n致敬最美劳动者，\\n医生护士冲向前，\\n个人安危抛一边，\\n警察叔叔守岗位，\\n维持秩序保平安，\\n小朋友们要牢记，\\n劳动人民最光荣，\\n最！光！荣！\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《妈妈的魔法》\", \"\", \"<div class=\\\"content\\\">我的妈妈有神奇的魔法，\\n变成我身上美丽的衣服。\\n变成我碗中好吃的饭菜，\\n变成我手中好玩的玩具。\\n变啊，变啊，\\n把我变高了，\\n把我变棒了。\\n在这只属于妈妈的节日里，\\n我想大声对妈妈说：妈妈，我爱你！\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《盲人摸象》\", \"\", \"<div class=\\\"content\\\">五个盲人摸大象，\\n摸出的答案不一样。\\n第一个说：大象是根大柱子。\\n第二个说：大象就像一堵墙。\\n第三个说：大象头上长有角。\\n第四个说：大象长的细又长。\\n第五个说：大象有根小辫子。\\n嗯…一定是个小姑娘！\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《虎大王照相》\", \"\", \"<div class=\\\"content\\\">大老虎，山中王。\\n端着相机去照相。\\n大王要给小猫照，\\n小猫吓得爬树啦。\\n大王要给小兔照，\\n小兔吓得钻洞啦。\\n大王要给白鹅照，\\n白鹅吓得跳河啦。\\n大王要给小鸟照，\\n小鸟吓得上天啦。\\n东奔西跑到处照，\\n最后啥也没照到。\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《五月五》\", \"\", \"<div class=\\\"content\\\">五月五，是端阳。\\n插艾叶，挂香囊。\\n五彩线，手腕绑。\\n划龙舟，喜洋洋。\\n吃粽子，蘸白糖。\\n愿您如意又安康。\\n</div>\"]}, {\"rate\": 0.4, \"type\": \"readText\", \"content\": [\"<div class=\\\"title\\\">《狗熊掰玉米》\", \"\", \"<div class=\\\"content\\\">大狗熊，有力气，\\n来到地里掰玉米。\\n掰一个，忙夹起。\\n手一举，掉脚底。\\n再掰一个再夹起，\\n手一举又掉脚底。\\n掰了半天数一数，\\n只有一个小玉米。\\n</div>\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
