INSERT INTO `article` VALUES (36, '9916aa6af8ec11f094dab4a9fc7c4063', '6', 0, '这个世上最廉价的是', '', '', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/poppy-1144084_1280.jpg', '/pages/article/detail?id=36', 'navigate', '[{\"type\": \"card\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/poppy-1144084_1280.jpg\", \"这个世上最廉价的是，<br/>一事无成的温柔，<br/>一贫如洗的真心，<br/>一厢情愿的等待。\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (37, '9916b279f8ec11f094dab4a9fc7c4063', '6', 0, '林深时见鹿', '', '', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/roe-deer-5502246_1280.jpg', '/pages/article/detail?id=37', 'navigate', '[{\"type\": \"card\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/roe-deer-5502246_1280.jpg\", \"林深时见鹿，<br/>海蓝时见鲸，<br/>梦醒时见你。<br/><br/>林深时雾起，<br/>海蓝时浪涌，<br/>梦醒时夜续。<br/><br/>不见鹿，<br/>不见鲸，<br/>亦不见你。\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (38, '9916b96cf8ec11f094dab4a9fc7c4063', '4', 1, '洛神赋', '[魏晋] 曹植', '古人有言：斯水之神，名曰宓妃', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-8601367_1280.jpg', '/pages/article/detail?id=38', 'navigate', '[{\"type\": \"title\", \"content\": \"洛神赋\"}, {\"type\": \"author\", \"content\": \"[魏晋] 曹植\"}, {\"type\": \"subTitle\", \"content\": \"黄初三年，余朝京师，还济洛川。古人有言：斯水之神，名曰宓妃。感宋玉对楚王神女之事，遂作斯赋。其辞曰：\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-8601367_1280.jpg\"}, {\"type\": \"readText\", \"content\": \"<div style=\\\"text-align: left;\\\">余从京域，言归东藩，背伊阙，越轘辕，经通谷，陵景山。日既西倾，车殆马烦。尔乃税驾乎蘅皋，秣驷乎芝田，容与乎阳林，流眄乎洛川。于是精移神骇，忽焉思散。俯则未察，仰以殊观。睹一丽人，于岩之畔。乃援御者而告之曰：“尔有觌于彼者乎？彼何人斯，若此之艳也！”御者对曰：“臣闻河洛之神，名曰宓妃。然则君王之所见也，无乃是乎！其状若何？臣愿闻之。”</div>\"}, {\"type\": \"readText\", \"content\": \"<div style=\\\"text-align: left;\\\">余告之曰：其形也，翩若惊鸿，婉若游龙。荣曜秋菊，华茂春松。髣髴兮若轻云之蔽月，飘飖兮若流风之回雪。远而望之，皎若太阳升朝霞；迫而察之，灼若芙蕖出渌波。穠纤得衷，修短合度。肩若削成，腰如约素。延颈秀项，皓质呈露。芳泽无加，铅华弗御。云髻峨峨，修眉联娟。丹唇外朗，皓齿内鲜。明眸善睐，靥辅承权。瓌姿艳逸，仪静体闲。柔情绰态，媚于语言。奇服旷世，骨像应图。披罗衣之璀粲兮，珥瑶碧之华琚。戴金翠之首饰，缀明珠以耀躯。践远游之文履，曳雾绡之轻裾。微幽兰之芳蔼兮，步踟蹰于山隅。于是忽焉纵体，以遨以嬉。左倚采旄，右荫桂旗。攘皓腕于神浒兮，采湍濑之玄芝。</div>\"}, {\"type\": \"readText\", \"content\": \"<div style=\\\"text-align: left;\\\">余情悦其淑美兮，心振荡而不怡。无良媒以接欢兮，托微波而通辞。愿诚素之先达兮，解玉佩以要之。嗟佳人之信修兮，羌习礼而明诗。抗琼珶以和予兮，指潜渊而为期。执眷眷之款实兮，惧斯灵之我欺。感交甫之弃言兮，怅犹豫而狐疑。收和颜而静志兮，申礼防以自持。</div>\"}, {\"type\": \"readText\", \"content\": \"<div style=\\\"text-align: left;\\\">于是洛灵感焉，徙倚彷徨。神光离合，乍阴乍阳。竦轻躯以鹤立，若将飞而未翔。践椒涂之郁烈，步蘅薄而流芳。超长吟以永慕兮，声哀厉而弥长。尔乃众灵杂沓，命俦啸侣。或戏清流，或翔神渚，或采明珠，或拾翠羽。从南湘之二妃，携汉滨之游女。叹匏瓜之无匹兮，咏牵牛之独处。扬轻袿之猗靡兮，翳修袖以延伫。体迅飞凫，飘忽若神。凌波微步，罗袜生尘。动无常则，若危若安；进止难期，若往若还。转眄流精，光润玉颜。含辞未吐，气若幽兰。华容婀娜，令我忘餐。</div>\"}, {\"type\": \"readText\", \"content\": \"<div style=\\\"text-align: left;\\\">于是屏翳收风，川后静波。冯夷鸣鼓，女娲清歌。腾文鱼以警乘，鸣玉銮以偕逝。六龙俨其齐首，载云车之容裔。鲸鲵踊而夹毂，水禽翔而为卫。于是越北沚，过南冈，纡素领，回清扬。动朱唇以徐言，陈交接之大纲。恨人神之道殊兮，怨盛年之莫当。抗罗袂以掩涕兮，泪流襟之浪浪。悼良会之永绝兮，哀一逝而异乡。无微情以效爱兮，献江南之明珰。虽潜处于太阴，长寄心于君王。忽不悟其所舍，怅神宵而蔽光。</div>\"}, {\"type\": \"readText\", \"content\": \"<div style=\\\"text-align: left;\\\">于是背下陵高，足往神留。遗情想像，顾望怀愁。冀灵体之复形，御轻舟而上溯。浮长川而忘反，思绵绵而增慕。夜耿耿而不寐，沾繁霜而至曙。命仆夫而就驾，吾将归乎东路。揽騑辔以抗策，怅盘桓而不能去。</div>\"}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (39, '9916bd98f8ec11f094dab4a9fc7c4063', '4', 2, '古代千古名联（一）', '', '中国古代千古名对（对联）集锦，对对经典！', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-8439196_1280.png', '/pages/article/detail?id=39', 'navigate', '[{\"type\": \"title\", \"content\": \"古代千古名联（一）\"}, {\"type\": \"subTitle\", \"content\": \"中国古代千古名对（对联）集锦，对对经典！\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-8439196_1280.png\"}, {\"type\": \"readText\", \"content\": \"绿水本无忧，因风皱面；<br/>青山原不老，为雪白头。\"}, {\"type\": \"readText\", \"content\": \"画上荷花和尚画；<br/>书临汉帖翰林书。\"}, {\"type\": \"readText\", \"content\": \"大肚能容，容天下难容之事；<br/>开口便笑，笑世间可笑之人。\"}, {\"type\": \"readText\", \"content\": \"朝云朝朝朝朝朝朝朝退；<br/>长水长长长长长长长流。\"}, {\"type\": \"readText\", \"content\": \"望江楼，<br/>望江流，<br/>望江楼下望江流，<br/>江楼千古，<br/>江流千古；<br/><br/>印月井，<br/>印月影，<br/>印月井中印月影，<br/>月井万年，<br/>月影万年。\"}, {\"type\": \"readText\", \"content\": \"有志者事竟成，<br/>破釜沉舟，<br/>百二秦关终属楚；<br/><br/>苦心人天不负，<br/>卧薪尝胆，<br/>三千越甲可吞吴。\"}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (40, '9916bf87f8ec11f094dab4a9fc7c4063', '4', 2, '古代千古名联（二）', '', '中国古代千古名对（对联）集锦，对对经典！', 0, '', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-8439215_1280.png', '/pages/article/detail?id=40', 'navigate', '[{\"type\": \"title\", \"content\": \"古代千古名联（二）\"}, {\"type\": \"subTitle\", \"content\": \"中国古代千古名对（对联）集锦，对对经典！\"}, {\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-8439215_1280.png\"}, {\"type\": \"readText\", \"content\": \"八百里湖山，知是何年图画；<br/>十万家烟火，尽归此处楼台。\"}, {\"type\": \"readText\", \"content\": \"五百里滇池，奔来眼底。<br/>披襟岸帻，喜茫茫空阔无边！<br/>看：<br/>东骧神骏，西翥灵仪，<br/>北走蜿蜒，南翔缟素。<br/>高人韵士，何妨选胜登临，<br/>趁蟹屿螺洲，梳裹就风鬟雾鬓，<br/>更苹天苇地，点缀些翠羽丹霞。<br/>莫辜负：<br/>四围香稻，万顷晴沙，<br/>九夏芙蓉，三春杨柳。<br/><br/>\\n          数千年往事，注到心头。<br/>把酒凌虚，叹滚滚英雄谁在？<br/>想：<br/>汉习楼船，唐标铁柱，<br/>宋挥玉斧，元跨革囊。<br/>伟烈丰功，费尽移山心力，<br/>尽珠帘画栋，卷不及暮雨朝云，<br/>便断碣残碑，都付与苍烟落照。<br/>只赢得：<br/>几杵疏钟，半江渔火，<br/>两行秋雁，一枕清霜。\\n        \"}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);
INSERT INTO `article` VALUES (41, '9916c16df8ec11f094dab4a9fc7c4063', '1,2', 1, '语文高频考点知识梳理（图片）', '李兆', '新一上语文高频考点知识梳理（十八个必背知识点）（10页）', 100, 'active', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/ai-generated-9775091_1280.webp', '/pages/article/detail?id=41', 'navigate', '[{\"type\": \"title\", \"content\": \"语文高频考点知识梳理\"}, {\"type\": \"subTitle\", \"content\": \"新一上语文高频考点知识梳理（十八个必背知识点）（10页）\"}, {\"type\": \"image\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0001.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0002.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0003.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0004.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0005.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0006.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0007.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0008.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0009.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E6%96%B0%E4%B8%80%E4%B8%8A%E8%AF%AD%E6%96%87%E9%AB%98%E9%A2%91%E8%80%83%E7%82%B9%E7%9F%A5%E8%AF%86%E6%A2%B3%E7%90%86-0010.jpg\"]}]', '2026-01-24 14:19:11', '2026-01-24 14:19:11', 0);

-- ----------------------------
-- Table structure for banner
-- ----------------------------
DROP TABLE IF EXISTS `banner`;
CREATE TABLE `banner`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '类型(image/video等)',
  `image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图片URL',
  `url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '跳转链接',
  `seq` int NULL DEFAULT NULL COMMENT '排序序号',
  `jump_to` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'navigate' COMMENT '跳转方式',
  `created_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NULL DEFAULT 0 COMMENT '删除标识(0:正常 1:已删除)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_title`(`title` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_seq`(`seq` ASC) USING BTREE,
  INDEX `idx_created_time`(`created_time` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'banner表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of banner
-- ----------------------------
INSERT INTO `banner` VALUES (1, '天空青草', 'image', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/微信图片_20251117231227_34_2.jpg', '/pages/article/detail?id=1', 0, 'navigate', '2026-01-24 14:58:07', '2026-01-24 14:58:07', 0);
INSERT INTO `banner` VALUES (2, '图书馆', 'image', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/微信图片_20251117231226_32_2.jpg', '/pages/video/play?mode=single&id=2', 0, 'navigate', '2026-01-24 14:58:07', '2026-01-24 14:58:07', 0);
INSERT INTO `banner` VALUES (3, '优雅聆听', 'image', 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/微信图片_20251117231226_33_2.jpg', '/static/hanyupinyin.html', 0, 'webview', '2026-01-24 14:58:07', '2026-01-24 14:58:07', 0);

-- ----------------------------
-- Table structure for book
-- ----------------------------
DROP TABLE IF EXISTS `book`;
CREATE TABLE `book`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `uuid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT (REPLACE(LOWER(UUID()), '-', '')) COMMENT '唯一标识(无中划线，全小写)',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '类型',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '书名',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作者',
  `owner` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '所有者',
  `score` decimal(3, 1) NULL DEFAULT NULL COMMENT '评分',
  `seq` int NULL DEFAULT NULL COMMENT '排序序号',
  `cover` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '封面图URL',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '描述',
  `summaries` json NULL COMMENT '摘要列表(JSON格式)',
  `tags` json NULL COMMENT '标签列表(JSON格式)',
  `highlights` json NULL COMMENT '精彩片段列表(JSON格式)',
  `created_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NULL DEFAULT 0 COMMENT '删除标识(0:正常 1:已删除)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_uuid`(`uuid` ASC) USING BTREE,
  UNIQUE INDEX `UKe3h0bpkf6nvswp9it9w4918ra`(`uuid` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_author`(`author` ASC) USING BTREE,
  INDEX `idx_seq`(`seq` ASC) USING BTREE,
  INDEX `idx_created_time`(`created_time` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '书籍表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of book
-- ----------------------------
INSERT INTO `book` VALUES (1, '8af87d1df85b11f094dab4a9fc7c4063', '1,4', '红楼梦', '曹雪芹', '李兆', 9.7, 100, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20260113234828_231_2.jpg', '一部中国文学史上的鸿篇巨制，以其丰富的思想内容、伟大的艺术成就和深远的文化影响成为中国古典文学史上的一朵奇葩。', '[\"《红楼梦》又名《石头记》，是中国古典小说的巅峰之作，位居“中国古典四大名著”之首。\", \"以贾、史、王、薛四大家族的兴衰为背景，以富贵公子贾宝玉为视角，以贾宝玉与林黛玉、薛宝钗的爱情婚姻悲剧为主线，描绘了一些闺阁佳人的人生百态，展现了真正的人性美和悲剧美，是一部从各个角度展现女性美以及中国古代社会百态的史诗性著作。\"]', '[\"必读\", \"经典推荐\", \"珍藏\"]', '[\"满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味？\", \"假作真时真亦假，无为有处有还无。\", \"世事洞明皆学问，人情练达即文章。\", \"<div style=\\\"font-weight: bold;\\\">莫失莫忘，仙寿恒昌；不离不弃，芳龄永继。</div>\", \"滴不尽相思血泪抛红豆，开不完春柳春花满画楼，睡不稳纱窗风雨黄昏后，忘不了新愁与旧愁。\", \"恰便似遮不住的青山隐隐，流不断的绿水悠悠。\", \"世人都晓神仙好，惟有功名忘不了！古今将相在何方？荒冢一堆草没了。\", \"霁月难逢，彩云易散，心比天高，身为下贱。风流灵巧招人怨，寿夭多因诽谤生，多情公子空牵念。\", \"欲洁何曾洁，云空未必空。可怜金玉质，终陷淖泥中。\", \"人有聚就有散，聚时欢喜，到散时岂不清冷？既清冷则伤感，所以不如倒是不聚的好。\", \"幸于始者怠于终，缮其辞者嗜其利。\", \"不求大士瓶中露，为乞孀娥槛外梅。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (2, '8af8a30bf85b11f094dab4a9fc7c4063', '1,4', '西游记', '吴承恩', '李兆', 9.5, 100, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20260113234828_231_2.jpg', '中国古代第一部浪漫主义章回体神魔小说，以奇幻笔法讲述取经之路，寓含修心证道的深刻哲理。', '[\"《西游记》是中国神魔小说的经典之作，讲述了唐僧师徒四人西天取经、历经九九八十一难的故事。\", \"小说以孙悟空出世、大闹天宫为开端，以唐僧收服孙悟空、猪八戒、沙僧为徒，一同前往西天取经为主线，通过一系列降妖伏魔的险阻，歌颂了不畏艰险、追求真理的精神，并塑造了孙悟空这一充满反抗与智慧精神的经典形象。\"]', '[\"神话\", \"冒险\", \"修心\"]', '[\"<div style=\'font-weight: bold;\'>宁恋本乡一捻土，莫爱他乡万两金。</div>\", \"山高自有客行路，水深自有渡船人。\", \"观棋柯烂，伐木丁丁，云边谷口徐行，卖薪沽酒，狂笑自陶情。\", \"扫地恐伤蝼蚁命，爱惜飞蛾纱罩灯。\", \"世间事，常难遂人愿，且看明月又有几回圆？\", \"你紧闭双眼，还说什么四大皆空？你若真的四大皆空，为什么不敢睁眼看我？你若真的睁眼看我，我不信你会两眼空空……\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (3, '8af8ab81f85b11f094dab4a9fc7c4063', '1,4', '三国演义', '罗贯中', '李兆', 9.5, 100, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20260113234828_231_2.jpg', '中国第一部长篇章回体历史演义小说，以宏大的叙事结构描绘了东汉末年至西晋初年的百年风云，被誉为“谋略之书，英雄之史”。', '[\"《三国演义》全名为《三国志通俗演义》，以陈寿《三国志》为蓝本，艺术化地再现了魏、蜀、吴三国之间的政治与军事斗争。\", \"小说以“天下大势，分久必合，合久必分”为历史脉络，集中描绘了官渡之战、赤壁之战等波澜壮阔的战争场面，塑造了诸葛亮、周瑜、关羽、曹操、吕布、太史慈等数百个性格鲜明的英雄形象，深刻影响了中国民众的历史观与价值观。\"]', '[\"历史\", \"战争\", \"谋略\"]', '[\"滚滚长江东逝水，浪花淘尽英雄。是非成败转头空。青山依旧在，几度夕阳红。<br/>白发渔樵江渚上，惯看秋月春风。一壶浊酒喜相逢。古今多少事，都付笑谈中。\", \"天下大势，分久必合，合久必分。\", \"<div style=\'font-weight: bold;\'>大丈夫生居天地间，岂能郁郁久居人下！</div>\", \"人中吕布，马中赤兔。\", \"我剑也未尝不利！\", \"大丈夫生于乱世，当带三尺剑立不世之功；今所志未遂，奈何死乎！\", \"宁教我负天下人，休教天下人负我。\", \"曲有误，周郎顾\", \"既生瑜，何生亮！\", \"大丈夫处世，不能立功建业，不几与草木同腐乎！\", \"玉可碎，而不可改其白；竹可焚，而不可毁其节；身虽死，名可垂于竹帛也。\", \"夫英雄者，胸怀大志，腹有良谋，有包藏宇宙之机，吞吐天地之志者也。\", \"吾闻勇将不怯死以苟免，壮士不毁节而求生。今日乃我死日也。汝可努力死战。\", \"将军有剑，不斩苍蝇。\", \"若举江东之众，决机于两阵之间，与天下争衡，卿不如我；举贤任能，使各尽力以保江东，我不如卿。\", \"我被酒色所伤，竟然如此憔悴。自今日始，戒酒！\", \"深感人生之艰难，就像那不息之长河，虽有东去大海之志，却流程缓慢，征程多艰。哎...然江河水总有入海之时，而人生之志，却常常难以实现，令人抱恨终生！\", \"涓滴之水汇成江河，已属不易，奔流向前，汇入大海之时，更会倍感自身之渺茫...\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (4, '8af8adaaf85b11f094dab4a9fc7c4063', '1,4', '水浒传', '施耐庵', '李兆', 9.0, 100, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20260113234828_231_2.jpg', '中国文学史上第一部白话文章回体小说，以官逼民反为主题，生动刻画了梁山泊一百零八位好汉的群像，堪称一部平民英雄的悲壮史诗。', '[\"《水浒传》又名《忠义水浒传》，讲述了北宋末年以宋江为首的绿林好汉在梁山泊聚义、接受招安、最终四散凋零的故事。\", \"小说通过“鲁智深倒拔垂杨柳”“武松打虎”“林冲雪夜上梁山”等经典篇章，深刻揭露了封建社会的黑暗与腐败，歌颂了反抗压迫、讲求义气的英雄精神，同时也对招安悲剧进行了深沉反思。\"]', '[\"英雄\", \"义气\", \"反抗\"]', '[\"太平本是将军定，不许将军见太平。\", \"饥不择食，寒不择衣，慌不择路，贫不择妻。\", \"世味薄方好，人情淡最长。\", \"失群的孤雁，趁月明独自贴天飞；漏网的活鱼，乘水势翻身冲浪跃。不分远近，岂顾高低。心忙撞倒路行人，脚快有如临阵马。\", \"我于路不曾害！酒也吃得，肉也吃得，饭也吃得，路也走得\", \"不曾害，不曾害！打了倒干净。我不要留这一顿寄库棒，寄下倒是钩肠债，几时得了！\", \"平生不修善果，只爱杀人放火。忽地顿开金枷，这里扯断玉锁。咦！钱塘江上潮信来，今日方知我是我。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (5, '8af8b4b8f85b11f094dab4a9fc7c4063', '1,5', '道德经', '老子', '李兆', 9.9, 1000, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_212831.jpg', '道家哲学的开山之作，被誉为“万经之王”，以五千余言的深邃智慧阐述了宇宙、自然、人生的根本规律。', '[\"《道德经》共八十一章，分《道经》与《德经》两部分，系统阐述了“道”的本质、规律及“无为而治”“柔弱胜刚强”等核心思想。其文辞简约而意境深远，既包含深邃的宇宙观与政治哲学，又富含个人修养与处世智慧，对中华文化乃至世界哲学产生了不可估量的影响。\"]', '[\"哲学\", \"道家经典\", \"智慧\"]', '[\"<div style=\\\"font-weight: bold;\\\">道可道，非常道；名可名，非常名。</div>\", \"上善若水，水善利万物而不争。\", \"治大国，若烹小鲜。\", \"祸兮福之所倚，福兮祸之所伏。\", \"大方无隅，大器晚成，大音希声，大象无形。\", \"知人者智，自知者明。胜人者有力，自胜者强。\", \"合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。\", \"天下难事，必作于易；天下大事，必作于细。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (6, '8af8b71af85b11f094dab4a9fc7c4063', '1,5', '诗经', '佚名', '李兆', 9.8, 999, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_212853.jpg', '中国文学的光辉起点，第一部诗歌总集，收录了西周初年至春秋中叶的诗歌305篇，全面反映了先秦时期的社会风貌与人民情感。', '[\"《诗经》在内容上分为风、雅、颂三部分，其中“国风”是地方民歌，最为后人传诵。其开创的“赋、比、兴”艺术手法和现实主义风格，奠定了中国诗歌的优良传统，是中华文化精神和审美情趣的重要源头。\"]', '[\"诗歌\", \"文学源头\", \"经典\"]', '[\"<div style=\\\"font-weight: bold;\\\">关关雎鸠，在河之洲。窈窕淑女，君子好逑。</div>\", \"蒹葭苍苍，白露为霜。所谓伊人，在水一方。\", \"昔我往矣，杨柳依依。今我来思，雨雪霏霏。\", \"知我者，谓我心忧；不知我者，谓我何求。\", \"投我以木桃，报之以琼瑶。匪报也，永以为好也！\", \"高山仰止，景行行止。虽不能至，心向往之。\", \"死生契阔，与子成说。执子之手，与子偕老。\", \"他山之石，可以攻玉。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (7, '8af8bb21f85b11f094dab4a9fc7c4063', '1,5', '状元文章', '《中国古代状元文章》 编委会', '李兆', 9.7, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_220303.jpg', '一部精选中国古代科举制度下顶级精英——状元们经典应试文章的汇编集，展现了传统士人学识、才华与思想的高度。', '[\"本书系统收录了自唐至清各代有代表性的状元文章，包括策、论、赋、诏诰等多种文体。通过这些文章，读者可以窥见古代知识精英对治国方略、社会伦理、历史文化等核心问题的思考，感受科举文化的精髓与文采之美。\"]', '[\"科举\", \"古文\", \"历史\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (8, '8af91f6ff85b11f094dab4a9fc7c4063', '1,4', '红楼梦（彩绘）', '[清] 孙温', '李兆', 9.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213125.jpg', '以清代画家孙温所绘工笔重彩《全本红楼梦》图册为核心的彩绘版，用230幅巨制画作，将文学经典转化为视觉艺术的盛宴。', '[\"此版以孙温耗费数十年心血绘制的全景式连环画为基础，生动再现了《红楼梦》的主要人物与经典情节。画风精细华美，色彩浓郁，情节连贯，被誉为“红楼绘本的巅峰之作”，为读者理解与欣赏《红楼梦》提供了独特的艺术视角。\"]', '[\"彩绘本\", \"艺术\", \"收藏\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (9, '8af9217bf85b11f094dab4a9fc7c4063', '1,5', '闲情偶寄', '[清] 李渔', '李兆', 9.2, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_215840.jpg', '明末清初文学家、生活美学家李渔的代表作，一部系统论述生活艺术与审美情趣的“古代生活百科全书”。', '[\"全书分词曲部、演习部、声容部、居室部、器玩部、饮馔部、种植部、颐养部八部分。内容涵盖戏曲理论、园林建筑、室内装饰、美食养生、花草种植乃至修身养性等，集中体现了作者独特的艺术见解与精致的生活哲学。\"]', '[\"生活美学\", \"明清小品\", \"艺术理论\"]', '[\"开卷之初，当以奇句夺目，使之一见而惊。\", \"变则新，不变则腐；变则活，不变则板。\", \"情为主，景是客。说景即是说情。\", \"乐不在外而在心，心以为乐，则是境皆乐；心以为苦，则无境不苦。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (10, '8af922d9f85b11f094dab4a9fc7c4063', '1', '古代诗词名句赏析', '吕周聚 编著', '李兆', 0.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_212909.jpg', '一部精选中国古代诗词经典名句并进行深入浅出赏析的工具书与读本，帮助读者快速把握古典诗词的精髓与美感。', '[\"本书按主题或意境分类辑录了自《诗经》至清代诗词中的千古名句。每句名句均附有详细的赏析文字，解读其背景、内涵、艺术特色及情感意境，是学习、鉴赏和引用古典诗词的实用指南。\"]', '[\"诗词鉴赏\", \"工具书\", \"名句集锦\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (11, '8af92437f85b11f094dab4a9fc7c4063', '1', '说文解字', '朱立春 编著', '李兆', 0.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_220412.jpg', '一部基于东汉许慎原著《说文解字》进行现代解读与整理的普及读本，系统介绍了汉字起源、构造与演变的基本知识。', '[\"本书选取了《说文解字》中的核心部分，以现代视角和语言进行解释，并配有丰富例证。旨在帮助现代读者了解汉字的构形规律（如“六书”）、本义源流，感受汉字文化的博大精深，是学习语言文字和传统文化的入门读物。\"]', '[\"文字学\", \"工具书\", \"传统文化\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (12, '8af92577f85b11f094dab4a9fc7c4063', '6', '时光知味', '白落梅', '李兆', 8.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_212957.jpg', '当代散文作家白落梅的散文集，以其一贯的清丽婉约、禅意悠远的笔触，书写岁月流转中的静好、感悟与深情。', '[\"全书通过一系列记叙生活点滴、追忆过往、品味自然的散文，抒发了对时间、人生、情感的独特感悟。文字纯净优美，意境空灵，引导读者在纷繁世事中寻得内心的宁静与诗意，体现了作者“做个清淡女子”的生活美学追求。\"]', '[\"散文\", \"治愈\", \"生活感悟\"]', '[\"时光如水，总是无言。你若安好，便是晴天。\", \"在这喧闹的凡尘，我们都需要有适合自己的地方，用来安放灵魂。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (13, '8af926cef85b11f094dab4a9fc7c4063', '6', '陌上花开', '安意如', '李兆', 8.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213016.jpg', '安意如古典诗词赏析系列代表作之一，以细腻感性的现代笔触，重新解读与演绎古典诗词背后的情感故事与生命意境。', '[\"本书选取了从汉代至唐代的经典乐府诗词名篇，结合历史背景与个人想象，进行散文式的解读与扩写。\", \"作者将古典情怀与现代意识熔于一炉，带领读者穿越时空，感受古代男女的爱恨情仇、生命悲欢，文字优美，情感充沛。\"]', '[\"诗词赏析\", \"散文随笔\", \"古典情怀\"]', '[\"陌上花开，可缓缓归矣。\", \"不是无情，亦非薄幸，只是我们一生中会遇上很多人，真正能停留驻足的又有几个？\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (14, '8af95d68f85b11f094dab4a9fc7c4063', '6', '美得令人心醉的宋词', '顾非熊', '李兆', 8.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213328.jpg', '一部专注于宋代词作之美的鉴赏读物，精选极富艺术感染力的宋词佳作，以唯美的语言解读其意境、情感与韵律之美。', '[\"本书精选了苏轼、辛弃疾、李清照、柳永等数十位宋词名家的巅峰之作。赏析文字侧重对词作意境之美的捕捉与再现，语言生动形象，情感饱满，旨在让读者直观感受宋词“无言而有画意”的独特魅力。\"]', '[\"宋词\", \"诗词鉴赏\", \"唯美\"]', '[\"两情若是久长时，又岂在朝朝暮暮。\", \"众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。\", \"此情无计可消除，才下眉头，却上心头。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (15, '8af96cf2f85b11f094dab4a9fc7c4063', '8', '时间重生', '[美] 李·斯莫林（Lee Smolin）', '李兆', 9.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_220424.jpg', '理论物理学家李斯莫林的科普著作，挑战了物理学中时间仅是幻觉的传统观念，大胆论证时间的真实性和宇宙演化的方向性。', '[\"本书从物理学史和前沿理论出发，批判了牛顿、爱因斯坦以来将时间视为静态背景的观点。\", \"作者结合量子引力、宇宙学等最新成果，提出“时间真实存在且宇宙在不断演化选择中诞生”的新范式，是一场关于时间本质的思想冒险。\"]', '[\"科普\", \"物理学\", \"哲学思考\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (16, '8af96ef4f85b11f094dab4a9fc7c4063', '15', '摄影笔记', '宁思潇潇', '李兆', 0.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_212931.jpg', '一部深受摄影爱好者欢迎的入门与进阶指南，以通俗易懂的语言和大量实例，系统讲解摄影基础知识与实战技巧。', '[\"本书从相机原理、曝光三要素、构图法则、用光技巧等基础讲起，逐步深入到不同题材（人像、风光、纪实等）的拍摄方法。强调“实战”与“理解”，语言风趣幽默，配有大量对比图例和实拍参数，旨在帮助读者快速建立系统的摄影知识体系，拍出好照片。\"]', '[\"摄影\", \"教程\", \"实用技能\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (17, '8af97046f85b11f094dab4a9fc7c4063', '2', '基础知识手册（高中英语）', '薛金星 主编', '李兆', 9.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213204.jpg', '高中英语学科经典的教辅工具书系列之一，系统梳理、归纳了高中阶段英语学科必须掌握的全部基础知识点和语法体系。', '[\"本书涵盖了高中英语的词汇、语法、句法、题型解题方法等核心内容，采用图表、口诀、辨析等方式进行清晰呈现。旨在帮助学生构建完整的英语知识网络，便于随时查阅、巩固记忆，是应对日常学习与升学考试的实用工具书。\"]', '[\"教辅\", \"工具书\", \"英语\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (18, '8af971c6f85b11f094dab4a9fc7c4063', '6', '愿你迷路到我身旁', '蕊希', '李兆', 0.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213055.jpg', '其实从未迷路，在遇见你之前，就把人生当作一场自由自在的漫步。', '[\"书中收录了多个独立的短篇故事，聚焦都市年轻人的情感困惑、成长伤痛以及对爱与希望的坚守。文字真诚质朴，情感细腻动人，旨在告诉读者：即使曾经历迷惘与孤单，最终都会找到属于自己的温暖归宿。\"]', '[\"情感\", \"治愈\", \"青春文学\"]', '[\"其实从未迷路，在遇见你之前，就把人生当作一场自由自在的漫步。\", \"愿你迷路到我身旁，然后余生，都是你。\", \"爱是积累，不爱也是。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (19, '8af9730df85b11f094dab4a9fc7c4063', '10', '变通', '宿文渊', '李兆', 0.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213040.jpg', '一部探讨为人处世智慧与方法的通俗读物，结合古今中外案例，阐述在坚守原则的前提下，如何灵活应变以应对复杂现实。', '[\"本书从思维、心态、沟通、处事等多个角度，分析“变通”的必要性与具体方法。强调“变通”不是圆滑世故，而是审时度势的智慧、打破僵局的钥匙，旨在帮助读者在生活与工作中更加从容、高效地解决问题。\"]', '[\"处世智慧\", \"成功学\", \"自我提升\"]', '[\"变则通，通则久。\", \"水随形而方圆，人随势而变通。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (20, '8af975aff85b11f094dab4a9fc7c4063', '10', '博弈论', '翟文明', '李兆', 0.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_220402.jpg', '一本面向大众的博弈论入门读物，用浅显的语言和生动的案例，介绍博弈论的基本概念、经典模型及其在生活、商业、决策中的应用。', '[\"本书系统讲解了纳什均衡、囚徒困境、智猪博弈等核心理论模型。结合大量历史故事、商业竞争、日常决策等现实案例，揭示博弈背后的逻辑与策略，帮助读者提升在互动决策中的理性分析与策略选择能力。\"]', '[\"经济学\", \"思维方法\", \"决策\"]', '[\"<div style=\\\"font-weight: bold; color: #7a5be1;\\\">悲剧的本质并不是不幸，而是事物无情活动的严肃性。但这种命运的必然性，只有通过人生中真实的不幸遭遇才能说明。</div>\", \"<div style=\\\"font-weight: bold; color: #7a5be1;\\\">正确的道路是什么我们不一定知道，但却不要把时间浪费在错误的道路上，不要在错误的道路上走得太远。</div>\", \"<div style=\\\"font-weight: bold;\\\">学会放弃，学会做出适当的牺牲，避免在错误的道路上走得太远，这就是成功的重要法则。</div>\", \"博奕论是指双方或者多方在竟争、合作、冲突等情况下，充分了解各方信息，并依此选择一种能为本方争取最大利益的最优决策的理论。\", \"纳什均衡，比喻成锅里的乒乓球：把几个乒乓球放到锅里，它们便会向锅底滚去，并在锅底相互碰撞，最后停住不动的时候便达成了一种平衡，也就是纳什均衡。\", \"<div style=\\\"font-weight: bold;\\\">机会成本：</div>为了得到某种东西，而所要放弃的另一些东西的最高价值。\", \"<div style=\\\"font-weight: bold;\\\">沉没成本：</div>已经发生、无法通过现在或将来的任何决策收回的成本。\", \"<div style=\\\"font-weight: bold;\\\">马太效应：</div>一种“强者愈强，弱者愈弱”的现象，即优势或劣势会不断累积和强化，导致两极分化。<br/>源自《圣经·马太福音》：“凡有的，还要加给他，叫他有余；凡没有的，连他所有的也要夺去。”\", \"<div style=\\\"font-weight: bold;\\\">边缘策略：</div>一种通过故意制造并操纵风险来威慑对手的博弈策略。策略实施者有意将局势推向灾难性边缘，迫使对手因害怕共同毁灭而让步。\", \"黑手党有一条规矩：若被警察抓住，不得供出其他成员，否则将受到严惩。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (21, '8af9773af85b11f094dab4a9fc7c4063', '10', '对答如流', '谢普', '李兆', 0.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_220352.jpg', '一部旨在提升人际沟通与即时应答能力的实用手册，汇集了各类常见场合下的对话技巧、应答策略与语言模板。', '[\"本书针对社交、面试、商务、即兴发言等多种场景，提供了应对方法和高情商回答范例。强调思维的敏捷性与表达的得体性，通过学习和练习，帮助读者在各种对话情境中都能做到思路清晰、应对自如、言语得体。\"]', '[\"沟通\", \"口才\", \"实用技巧\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (22, '8af97884f85b11f094dab4a9fc7c4063', '10', '魔鬼聊天术', '阮琦', '李兆', 0.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213028.jpg', '知名社交教练阮琦（“魔鬼咨询师”）的聊天技巧指南，专注于解决异性社交中的沟通难题，提供建立吸引力的具体方法与话术。', '[\"本书深入分析了异性交往中常见的沟通误区，并从心态、流程、技巧三个层面提供解决方案。通过大量真实的聊天记录解析，教授如何开启对话、建立联系、升级关系，旨在帮助读者提升情感社交中的自信与能力。\"]', '[\"两性沟通\", \"社交\", \"情感\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (23, '8af98054f85b11f094dab4a9fc7c4063', '10', '别让直性子毁了你', '冠诚', '李兆', 10.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213046.jpg', '一部探讨性格与处世关系的通俗心理学读物，分析“直性子”在人际交往中的利弊，并提供修炼情商、改善关系的具体建议。', '[\"本书指出“直率”与“鲁莽”的区别，剖析因过于直接而引发的沟通冲突与职场困境。通过案例与练习，引导读者学会换位思考、控制情绪、委婉表达，在保持真诚本心的同时，更圆融地处理人际关系。\"]', '[\"情商\", \"人际交往\", \"自我管理\"]', '[\"直言不讳是优点，但不懂分寸就是缺陷。\", \"说话的温度，决定了人生的高度。\"]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (24, '8af98237f85b11f094dab4a9fc7c4063', '15', '零基础学Java', '常建功 陈浩等', '李兆', 10.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213355.jpg', '一本面向编程初学者的Java语言入门教程，从零开始，循序渐进地讲解Java核心语法、面向对象编程及基础应用开发。', '[\"本书内容涵盖Java开发环境搭建、基础语法、数组、类与对象、继承、多态、接口、异常处理、常用类库等核心知识。采用“理论+示例+练习”的模式，图文并茂，步骤详细，旨在帮助没有任何编程经验的读者顺利入门Java，并建立扎实的编程思维。\"]', '[\"编程\", \"计算机\", \"教程\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (25, '8af9a3e0f85b11f094dab4a9fc7c4063', '15', 'PHP入门经典', '李慧 高飞等', '李兆', 10.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_213147.jpg', '一部系统全面的PHP网站开发入门教材，详细讲解PHP语言基础、MySQL数据库操作及动态网站构建的全流程。', '[\"本书从PHP环境配置、基本语法讲起，逐步深入到表单处理、会话控制、文件操作、面向对象编程以及使用PHP操作MySQL数据库。最后通过典型项目案例，带领读者完成一个完整的动态网站开发，理论与实践紧密结合，适合希望掌握PHP后端开发技能的初学者。\"]', '[\"编程\", \"PHP\", \"Web开发\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);
INSERT INTO `book` VALUES (26, '8af9a561f85b11f094dab4a9fc7c4063', '15', 'Excel超效率速成技', '诺立教育', '李兆', 10.0, 10, 'https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/IMG_20260114_212939.jpg', '一本汇集了Excel高效操作技巧与实用函数的实战手册，旨在帮助职场人士大幅提升表格处理、数据分析的效率与质量。', '[\"本书精选了工作中最常用、最能提升效率的Excel技巧，包括快捷键、数据整理、公式函数（如VLOOKUP、SUMIF）、数据透视表、图表制作等。\", \"以“解决问题”为导向，每个技巧配有明确的应用场景和操作步骤，即学即用，适合希望摆脱重复低效操作的Excel用户。\"]', '[\"办公软件\", \"效率工具\", \"职场技能\"]', '[]', '2026-01-23 21:00:50', '2026-01-23 21:00:50', 0);

-- ----------------------------
-- Table structure for category
-- ----------------------------
DROP TABLE IF EXISTS `category`;
CREATE TABLE `category`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `category_id` int NOT NULL COMMENT '分类ID',
  `category_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类名称',
  `type_id` int NULL DEFAULT NULL COMMENT '类型ID',
  `type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '类型名称',
  `sub_type_id` int NULL DEFAULT NULL COMMENT '子类型ID',
  `sub_type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '子类型名称',
  `created_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NULL DEFAULT 0 COMMENT '删除标识(0:正常 1:已删除)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_category_type`(`category_id` ASC, `type_id` ASC, `sub_type_id` ASC) USING BTREE,
  INDEX `idx_category_id`(`category_id` ASC) USING BTREE,
  INDEX `idx_created_time`(`created_time` ASC) USING BTREE,
  INDEX `idx_is_deleted`(`is_deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分类类型映射表' ROW_FORMAT = Dynamic;

