INSERT INTO `task` VALUES (1, '李兮拉丁舞学习任务', 2, '李兆', '李兮', '完成每周两次的拉丁舞课程学习。', 0, 60, '完成一次舞蹈表演，获得家人的认可，并录制视频。', '[{\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251218204850_133_2.jpg\", \"description\": \"拉丁舞蹈裙\"}]', '[{\"type\": \"video\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/video/dance/WeChat_20250505092731.mp4\", \"description\": \"拉丁舞教学视频\"}]', '[]', 1746057600000, 1746057600000, 1777507200000, '2026-01-24 16:32:13', '2026-01-24 16:32:13', 0);
INSERT INTO `task` VALUES (2, '何烨笼初二上学期单词记忆任务', 2, '李芳', '何烨笼', '每天记忆25个英语单词，确保在学期结束前掌握所有课程要求的单词量。', 0, 20, '以“默默背单词”检验记忆效果，掌握词汇不低于95%。', '[{\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251218204849_132_2.jpg\", \"description\": \"时尚电子词典\"}]', '[]', '[]', 1756684800000, 1756684800000, 1767139200000, '2026-01-24 16:32:13', '2026-01-24 16:32:13', 0);
INSERT INTO `task` VALUES (3, '李若绘画兴趣培养任务', 3, '李兆', '李若', '每周完成一幅绘画作品。', 0, 100, '累积完成5幅绘画作品，并在家庭聚会上进行展示。', '[{\"type\": \"image\", \"content\": \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251218204851_134_2.jpg\", \"description\": \"高级绘画工具\"}]', '[]', '[{\"type\": \"image\", \"content\": [\"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003935_117_2.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003937_119_2.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003939_120_2.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251216003950_126_2.jpg\", \"https://yizhao-1259410276.cos.ap-shanghai.myqcloud.com/images/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20251217212150_131_2.jpg\"], \"description\": \"李若作品展\"}]', 1756684800000, 1756684800000, 1767139200000, '2026-01-24 16:32:13', '2026-01-24 16:32:13', 0);

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uuid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户UUID',
  `phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '手机号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `sex` int NULL DEFAULT NULL,
  `birthday` timestamp NULL DEFAULT NULL,
  `alias` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `nickname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `role` int NOT NULL COMMENT '类型（1-100）\r\n1-管理员 \r\n2-家长 \r\n3-学生',
  `password` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `captcha` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '验证码',
  `token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '用户token',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标识',
  PRIMARY KEY (`id` DESC) USING BTREE,
  UNIQUE INDEX `uk_uuid`(`uuid` ASC) USING BTREE,
  UNIQUE INDEX `uk_phone`(`phone` ASC) USING BTREE,
  UNIQUE INDEX `UK1xc1iry6gqjrvh5cpajiq7l2f`(`uuid` ASC) USING BTREE,
  UNIQUE INDEX `UK589idila9li6a4arw1t8ht1gx`(`phone` ASC) USING BTREE,
  CONSTRAINT `user_chk_1` CHECK (`role` between 1 and 100)
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户信息表' ROW_FORMAT = Dynamic;

